"use client";

import { useEffect } from "react";

export type MarketingSitePage = "home" | "features" | "contact";

const SITE_CSS = "@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');\n:root {\n    --royal: #1E40AF;\n    --royal-deep: #1E3A8A;\n    --royal-bright: #2563EB;\n    --royal-soft: #EFF4FE;\n    --royal-line: #DCE5F8;\n    --gold: #D4A93A;\n\n    --ink: #0B1A33;\n    --ink-2: #1A2742;\n    --slate: #4A5778;\n    --slate-2: #6B7895;\n    --grey-1: #9BA5BD;\n    --grey-2: #CDD3E0;\n    --grey-3: #E5E9F1;\n\n    --paper: #FFFFFF;\n    --paper-2: #FAFBFD;\n    --paper-3: #F4F6FB;\n\n    --hairline: #E5E9F1;\n    --hairline-soft: #F0F2F8;\n\n    --sans: 'Manrope', system-ui, -apple-system, sans-serif;\n    --mono: 'JetBrains Mono', ui-monospace, monospace;\n  }\n\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n\n  html { scroll-behavior: smooth; }\n\n  body {\n    font-family: var(--sans);\n    color: var(--ink);\n    background: var(--paper);\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n    line-height: 1.5;\n    overflow-x: hidden;\n    font-size: 16px;\n  }\n\n  a { color: inherit; text-decoration: none; }\n  img { display: block; max-width: 100%; }\n\n  /* ============ Navigation ============ */\n  .nav {\n    position: sticky;\n    top: 0;\n    z-index: 100;\n    background: rgba(255, 255, 255, 0.92);\n    backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px);\n    border-bottom: 1px solid var(--hairline);\n  }\n\n  .nav-inner {\n    max-width: 1320px;\n    margin: 0 auto;\n    padding: 18px 56px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 48px;\n  }\n\n  .nav-logo {\n    display: flex;\n    align-items: center;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n\n  .nav-logo img {\n    height: 38px;\n    width: auto;\n  }\n\n  .nav-links {\n    display: flex;\n    gap: 40px;\n    align-items: center;\n    flex: 1;\n    justify-content: center;\n  }\n\n  .nav-link {\n    font-size: 15px;\n    font-weight: 500;\n    color: var(--slate);\n    cursor: pointer;\n    transition: color 0.2s ease;\n    letter-spacing: -0.005em;\n  }\n\n  .nav-link:hover { color: var(--ink); }\n\n  .nav-link.active { color: var(--ink); }\n\n  .nav-cta {\n    display: flex;\n    gap: 10px;\n    align-items: center;\n    flex-shrink: 0;\n  }\n\n  .mobile-nav-toggle {\n    display: none;\n    width: 48px;\n    height: 48px;\n    align-items: center;\n    justify-content: center;\n    border: 1px solid var(--hairline);\n    border-radius: 999px;\n    background: var(--paper);\n    color: var(--ink);\n    cursor: pointer;\n    transition: border-color 0.2s ease, background 0.2s ease;\n  }\n\n  .mobile-nav-toggle:hover {\n    border-color: var(--royal-line);\n    background: var(--royal-soft);\n  }\n\n  .mobile-nav-toggle svg {\n    width: 22px;\n    height: 22px;\n  }\n\n  .mobile-nav-toggle .icon-close { display: none; }\n\n  .nav.mobile-open .mobile-nav-toggle .icon-menu { display: none; }\n  .nav.mobile-open .mobile-nav-toggle .icon-close { display: block; }\n\n  .mobile-menu {\n    display: none;\n    border-top: 1px solid var(--hairline);\n    background: rgba(255, 255, 255, 0.98);\n    padding: 12px 20px 20px;\n  }\n\n  .mobile-menu-inner {\n    display: flex;\n    max-width: 1320px;\n    margin: 0 auto;\n    flex-direction: column;\n    gap: 8px;\n  }\n\n  .mobile-nav-link {\n    border-radius: 18px;\n    padding: 14px 16px;\n    color: var(--ink);\n    font-size: 16px;\n    font-weight: 700;\n    cursor: pointer;\n  }\n\n  .mobile-nav-link:hover,\n  .mobile-nav-link.active {\n    background: var(--royal-soft);\n    color: var(--royal);\n  }\n\n  .mobile-menu .btn {\n    justify-content: center;\n    margin-top: 8px;\n    width: 100%;\n  }\n\n  .btn {\n    font-family: var(--sans);\n    font-size: 15px;\n    font-weight: 600;\n    padding: 12px 24px;\n    border-radius: 999px;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    border: 1px solid transparent;\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    white-space: nowrap;\n    background: none;\n    letter-spacing: -0.01em;\n  }\n\n  .btn-ghost {\n    color: var(--ink);\n    border-color: var(--hairline);\n    background: var(--paper);\n  }\n\n  .btn-ghost:hover {\n    border-color: var(--ink);\n  }\n\n  .btn-primary {\n    background: var(--royal);\n    color: var(--paper);\n  }\n\n  .btn-primary:hover {\n    background: var(--royal-deep);\n  }\n\n  .btn-large {\n    padding: 16px 28px;\n    font-size: 16px;\n  }\n\n  /* ============ Page system ============ */\n  .page {\n    display: none;\n    animation: fadeIn 0.4s ease;\n  }\n\n  .page.active { display: block; }\n\n  @keyframes fadeIn {\n    from { opacity: 0; transform: translateY(8px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n\n  /* ============ Shared elements ============ */\n  .container {\n    max-width: 1320px;\n    margin: 0 auto;\n    padding: 0 56px;\n  }\n\n  .container-narrow {\n    max-width: 980px;\n    margin: 0 auto;\n    padding: 0 56px;\n  }\n\n  .eyebrow {\n    font-family: var(--sans);\n    font-size: 13px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.16em;\n    color: var(--royal);\n    margin-bottom: 28px;\n    display: inline-block;\n  }\n\n  /* ====== Display headline system, matching the live site ====== */\n  h1.display, h2.display {\n    font-family: var(--sans);\n    font-weight: 700;\n    color: var(--ink);\n    letter-spacing: -0.035em;\n    line-height: 1.02;\n  }\n\n  h1.display {\n    font-size: clamp(48px, 6.2vw, 88px);\n  }\n\n  h2.display {\n    font-size: clamp(38px, 4.6vw, 60px);\n    line-height: 1.05;\n    letter-spacing: -0.03em;\n  }\n\n  h3.display {\n    font-family: var(--sans);\n    font-weight: 700;\n    font-size: clamp(26px, 2.8vw, 34px);\n    line-height: 1.15;\n    letter-spacing: -0.02em;\n    color: var(--ink);\n  }\n\n  .lede {\n    font-family: var(--sans);\n    font-size: clamp(18px, 1.4vw, 21px);\n    line-height: 1.55;\n    color: var(--slate);\n    font-weight: 400;\n    letter-spacing: -0.01em;\n  }\n\n  .body-text {\n    font-size: 17px;\n    line-height: 1.65;\n    color: var(--slate);\n    letter-spacing: -0.005em;\n  }\n\n  /* ============ HOME - HERO ============ */\n  .hero {\n    padding: 80px 0 100px;\n  }\n\n  .hero-grid {\n    display: grid;\n    grid-template-columns: minmax(0, 0.86fr) minmax(520px, 1.18fr);\n    gap: 56px;\n    align-items: center;\n  }\n\n  .hero h1 {\n    font-weight: 700;\n    font-size: clamp(48px, 6.4vw, 84px);\n    line-height: 1.02;\n    letter-spacing: -0.038em;\n    color: var(--ink);\n    margin-bottom: 28px;\n  }\n\n  .hero-sub {\n    font-size: clamp(17px, 1.3vw, 20px);\n    line-height: 1.55;\n    color: var(--slate);\n    max-width: 540px;\n    margin-bottom: 40px;\n    letter-spacing: -0.005em;\n  }\n\n  .hero-actions {\n    display: flex;\n    gap: 12px;\n    align-items: center;\n    margin-bottom: 32px;\n    flex-wrap: wrap;\n  }\n\n  .hero-meta {\n    display: flex;\n    gap: 24px;\n    flex-wrap: wrap;\n  }\n\n  .hero-meta-item {\n    font-size: 14px;\n    color: var(--slate-2);\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    letter-spacing: -0.005em;\n  }\n\n  .hero-meta-item svg {\n    color: var(--royal);\n    flex-shrink: 0;\n  }\n\n  .hero-image {\n    aspect-ratio: 3/2;\n    width: min(114%, 780px);\n    min-height: clamp(380px, 36vw, 520px);\n    margin-left: -18px;\n    overflow: hidden;\n    border-radius: 18px;\n    position: relative;\n    isolation: isolate;\n    background: var(--paper-3);\n    box-shadow: 0 1px 2px rgba(11,26,51,0.04), 0 28px 60px -18px rgba(11,26,51,0.36);\n  }\n\n  .hero-image img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center 28%;\n    transition: transform 0.7s cubic-bezier(0.22,1,0.36,1);\n  }\n\n  .hero-image:hover img {\n    transform: scale(1.035);\n  }\n\n  .hero-image::after {\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    background: linear-gradient(to top, rgba(11,26,51,0.55), rgba(11,26,51,0) 55%);\n    pointer-events: none;\n  }\n\n  .hero-image-ring {\n    position: absolute;\n    inset: 0;\n    border-radius: 16px;\n    box-shadow: inset 0 0 0 1px rgba(255,255,255,0.14);\n    pointer-events: none;\n    z-index: 2;\n  }\n\n  .hero-badge {\n    position: absolute;\n    left: 18px;\n    bottom: 18px;\n    z-index: 3;\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 10px 16px 10px 12px;\n    border-radius: 14px;\n    background: rgba(11,26,51,0.42);\n    border: 1px solid rgba(255,255,255,0.18);\n    backdrop-filter: blur(10px);\n    -webkit-backdrop-filter: blur(10px);\n  }\n\n  .hero-badge-check {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    width: 34px;\n    height: 34px;\n    border-radius: 10px;\n    background: rgba(255,255,255,0.92);\n    color: var(--royal);\n    flex-shrink: 0;\n  }\n\n  .hero-badge-text {\n    display: flex;\n    flex-direction: column;\n    line-height: 1.25;\n  }\n\n  .hero-badge-text strong {\n    font-size: 14px;\n    font-weight: 700;\n    color: #fff;\n    letter-spacing: -0.01em;\n  }\n\n  .hero-badge-text em {\n    font-style: normal;\n    font-size: 12px;\n    font-weight: 500;\n    color: rgba(255,255,255,0.82);\n  }\n\n  /* ============ Trust band ============ */\n  .trust {\n    padding: 56px 0;\n    border-top: 1px solid var(--hairline);\n    border-bottom: 1px solid var(--hairline);\n    background:\n      radial-gradient(circle at 12% 18%, rgba(30, 64, 175, 0.08), transparent 32%),\n      linear-gradient(180deg, var(--paper) 0%, var(--paper-2) 100%);\n  }\n\n  .trust-inner {\n    display: grid;\n    grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.35fr);\n    gap: 48px;\n    align-items: center;\n    max-width: 1320px;\n    margin: 0 auto;\n    padding: 0 56px;\n  }\n\n  .trust-copy {\n    max-width: 430px;\n  }\n\n  .trust-label {\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 0.18em;\n    color: var(--royal);\n    font-weight: 700;\n    margin-bottom: 14px;\n  }\n\n  .trust-copy h2 {\n    font-size: clamp(26px, 2.6vw, 40px);\n    line-height: 1.08;\n    letter-spacing: -0.035em;\n    color: var(--ink);\n    margin-bottom: 18px;\n  }\n\n  .trust-copy p {\n    font-size: 16px;\n    line-height: 1.65;\n    color: var(--slate);\n    letter-spacing: -0.005em;\n  }\n\n  .trust-items {\n    display: grid;\n    grid-template-columns: repeat(5, minmax(0, 1fr));\n    gap: 12px;\n  }\n\n  .trust-item {\n    min-height: 132px;\n    border: 1px solid var(--hairline);\n    border-radius: 18px;\n    background: rgba(255, 255, 255, 0.82);\n    box-shadow: 0 18px 38px rgba(15, 23, 42, 0.05);\n    color: var(--ink);\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n    gap: 24px;\n    padding: 18px;\n    position: relative;\n    overflow: hidden;\n    font-size: 15px;\n    font-weight: 700;\n    letter-spacing: -0.015em;\n  }\n\n  .trust-item::after {\n    content: \"\";\n    position: absolute;\n    right: -28px;\n    bottom: -30px;\n    width: 88px;\n    height: 88px;\n    border-radius: 50%;\n    background: rgba(30, 64, 175, 0.08);\n  }\n\n  .trust-item:hover {\n    border-color: rgba(30, 64, 175, 0.25);\n    transform: translateY(-2px);\n    transition: transform 0.25s ease, border-color 0.25s ease;\n  }\n\n  .trust-icon {\n    width: fit-content;\n    border-radius: 999px;\n    border: 1px solid rgba(30, 64, 175, 0.14);\n    background: rgba(30, 64, 175, 0.06);\n    color: var(--royal);\n    padding: 5px 9px;\n    font-family: var(--mono);\n    font-size: 11px;\n    font-weight: 700;\n    letter-spacing: 0.08em;\n  }\n\n  /* ============ Three layers / SaaS feature blocks ============ */\n  .layers {\n    padding: 120px 0 100px;\n  }\n\n  .section-header {\n    max-width: 760px;\n    margin: 0 auto 64px;\n    text-align: center;\n  }\n\n  .section-header.left {\n    text-align: left;\n    margin-left: 0;\n  }\n\n  .layers-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 24px;\n  }\n\n  .layer-card {\n    background: var(--paper);\n    border: 1px solid var(--hairline);\n    border-radius: 12px;\n    padding: 0;\n    transition: all 0.3s ease;\n    position: relative;\n    overflow: hidden;\n    display: flex;\n    flex-direction: column;\n  }\n\n  .layer-card:hover {\n    border-color: var(--royal);\n    box-shadow: 0 20px 40px rgba(30, 64, 175, 0.08);\n    transform: translateY(-2px);\n  }\n\n  .layer-card-image {\n    aspect-ratio: 16/10;\n    background: var(--paper-3);\n    overflow: hidden;\n    position: relative;\n  }\n\n  .layer-card-image img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  .layer-card-num {\n    position: absolute;\n    top: 16px;\n    left: 16px;\n    background: var(--paper);\n    color: var(--royal);\n    padding: 6px 12px;\n    border-radius: 6px;\n    font-family: var(--mono);\n    font-size: 11px;\n    font-weight: 600;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    z-index: 2;\n  }\n\n  .layer-card-body {\n    padding: 32px 28px 28px;\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n  }\n\n  .layer-card-title {\n    font-size: 22px;\n    font-weight: 700;\n    line-height: 1.2;\n    letter-spacing: -0.02em;\n    color: var(--ink);\n    margin-bottom: 12px;\n  }\n\n  .layer-card-sub {\n    font-size: 15px;\n    line-height: 1.55;\n    color: var(--slate);\n    margin-bottom: 24px;\n    letter-spacing: -0.005em;\n  }\n\n  .layer-card-features {\n    list-style: none;\n    margin-bottom: 24px;\n  }\n\n  .layer-card-features li {\n    font-size: 14px;\n    line-height: 1.5;\n    color: var(--ink);\n    padding: 6px 0;\n    display: flex;\n    gap: 10px;\n    align-items: flex-start;\n    letter-spacing: -0.005em;\n  }\n\n  .layer-card-features li svg {\n    color: var(--royal);\n    flex-shrink: 0;\n    margin-top: 4px;\n  }\n\n  .layer-card-buyer {\n    margin-top: auto;\n    padding-top: 20px;\n    border-top: 1px solid var(--hairline);\n    font-size: 13px;\n    color: var(--slate-2);\n    letter-spacing: -0.005em;\n  }\n\n  .layer-card-buyer strong {\n    color: var(--ink);\n    font-weight: 700;\n    display: block;\n    margin-top: 2px;\n    font-size: 14px;\n  }\n\n  /* ============ Gift Aid hero ============ */\n  .gift-aid {\n    padding: 100px 0;\n    background: var(--ink);\n    color: var(--paper);\n    position: relative;\n    overflow: hidden;\n  }\n\n  .gift-aid::before {\n    content: '';\n    position: absolute;\n    top: -200px;\n    left: -200px;\n    width: 600px;\n    height: 600px;\n    background: radial-gradient(circle, rgba(37, 99, 235, 0.25) 0%, transparent 60%);\n  }\n\n  .gift-aid::after {\n    content: '';\n    position: absolute;\n    bottom: -200px;\n    right: -200px;\n    width: 600px;\n    height: 600px;\n    background: radial-gradient(circle, rgba(212, 169, 58, 0.12) 0%, transparent 60%);\n  }\n\n  .gift-aid-inner {\n    position: relative;\n    z-index: 2;\n  }\n\n  .gift-aid-grid {\n    display: grid;\n    grid-template-columns: 1fr 1.2fr;\n    gap: 80px;\n    align-items: center;\n  }\n\n  .gift-aid-image {\n    aspect-ratio: 4/5;\n    border-radius: 4px;\n    overflow: hidden;\n    position: relative;\n  }\n\n  .gift-aid-image img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    filter: brightness(0.9);\n  }\n\n  .gift-aid-content .eyebrow {\n    color: var(--gold);\n  }\n\n  .gift-aid-content h2 {\n    color: var(--paper);\n    font-weight: 700;\n    font-size: clamp(36px, 4.4vw, 56px);\n    line-height: 1.05;\n    letter-spacing: -0.03em;\n    margin-bottom: 24px;\n  }\n\n  .gift-aid-content h2 .gold { color: var(--gold); }\n\n  .gift-aid-content p {\n    color: rgba(255,255,255,0.7);\n    font-size: 18px;\n    line-height: 1.55;\n    margin-bottom: 36px;\n    letter-spacing: -0.005em;\n    max-width: 520px;\n  }\n\n  .gift-aid-stats {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 20px;\n    border-top: 1px solid rgba(255,255,255,0.12);\n    padding-top: 32px;\n  }\n\n  .gift-aid-stat-num {\n    font-family: var(--sans);\n    font-weight: 700;\n    font-size: 36px;\n    line-height: 1;\n    color: var(--gold);\n    margin-bottom: 8px;\n    letter-spacing: -0.03em;\n  }\n\n  .gift-aid-stat-label {\n    font-size: 13px;\n    color: rgba(255,255,255,0.7);\n    line-height: 1.4;\n    letter-spacing: -0.005em;\n  }\n\n  /* ============ Feature blocks (alternating image+text) ============ */\n  .feature-block {\n    padding: 100px 0;\n  }\n\n  .feature-block + .feature-block {\n    border-top: 1px solid var(--hairline);\n  }\n\n  .feature-block-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 80px;\n    align-items: center;\n  }\n\n  .feature-block.reverse .feature-block-grid > div:first-child {\n    order: 2;\n  }\n\n  .feature-block-image {\n    aspect-ratio: 5/4;\n    background: var(--paper-3);\n    border-radius: 4px;\n    overflow: hidden;\n    position: relative;\n  }\n\n  .feature-block-image img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  .feature-block h2 {\n    margin-bottom: 24px;\n  }\n\n  .feature-block p.body-text {\n    margin-bottom: 32px;\n  }\n\n  .feature-pills {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n    margin-bottom: 32px;\n  }\n\n  .feature-pill {\n    background: var(--royal-soft);\n    color: var(--royal);\n    padding: 6px 14px;\n    border-radius: 999px;\n    font-size: 13px;\n    font-weight: 600;\n    letter-spacing: -0.005em;\n  }\n\n  /* ============ \"What replaces what\" - 4 cards ============ */\n  .replaces {\n    padding: 100px 0;\n    background: var(--paper-2);\n    border-top: 1px solid var(--hairline);\n    border-bottom: 1px solid var(--hairline);\n  }\n\n  .replaces-grid {\n    display: grid;\n    grid-template-columns: repeat(2, 1fr);\n    gap: 16px;\n  }\n\n  .replaces-card {\n    background: var(--paper);\n    border: 1px solid var(--hairline);\n    border-radius: 12px;\n    padding: 32px 32px 36px;\n    transition: all 0.3s ease;\n  }\n\n  .replaces-card:hover {\n    border-color: var(--royal);\n    transform: translateY(-2px);\n  }\n\n  .replaces-card-icon {\n    width: 44px;\n    height: 44px;\n    background: var(--royal-soft);\n    border-radius: 10px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--royal);\n    margin-bottom: 20px;\n  }\n\n  .replaces-card h3 {\n    font-size: 19px;\n    font-weight: 700;\n    letter-spacing: -0.02em;\n    color: var(--ink);\n    margin-bottom: 10px;\n  }\n\n  .replaces-card p {\n    font-size: 15px;\n    line-height: 1.55;\n    color: var(--slate);\n    letter-spacing: -0.005em;\n  }\n\n  /* ============ Province section ============ */\n  .province {\n    padding: 100px 0;\n  }\n\n  .province-grid {\n    display: grid;\n    grid-template-columns: 1fr 1.05fr;\n    gap: 80px;\n    align-items: center;\n  }\n\n  .province-image {\n    aspect-ratio: 5/6;\n    background: var(--paper-3);\n    border-radius: 4px;\n    overflow: hidden;\n  }\n\n  .province-image img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  /* ============ Quote ============ */\n  .quote-section {\n    padding: 100px 0;\n    background: var(--paper-2);\n    border-top: 1px solid var(--hairline);\n  }\n\n  .quote-block {\n    max-width: 880px;\n    margin: 0 auto;\n    text-align: center;\n  }\n\n  .quote-mark {\n    font-family: var(--sans);\n    font-size: 80px;\n    line-height: 0.6;\n    color: var(--royal);\n    margin-bottom: 16px;\n    font-weight: 700;\n  }\n\n  .quote-text {\n    font-size: clamp(22px, 2.6vw, 32px);\n    line-height: 1.35;\n    color: var(--ink);\n    margin-bottom: 28px;\n    letter-spacing: -0.02em;\n    font-weight: 600;\n  }\n\n  .quote-attr {\n    font-size: 13px;\n    color: var(--slate-2);\n    text-transform: uppercase;\n    letter-spacing: 0.16em;\n    font-weight: 600;\n  }\n\n  /* ============ CTA Band ============ */\n  .cta-band {\n    padding: 100px 0;\n    background: var(--ink);\n    color: var(--paper);\n    position: relative;\n    overflow: hidden;\n    text-align: center;\n  }\n\n  .cta-band::before {\n    content: '';\n    position: absolute;\n    inset: 0;\n    background: radial-gradient(ellipse at center, rgba(37, 99, 235, 0.2) 0%, transparent 60%);\n  }\n\n  .cta-band-inner {\n    position: relative;\n    z-index: 2;\n    max-width: 760px;\n    margin: 0 auto;\n  }\n\n  .cta-band h2 {\n    font-weight: 700;\n    font-size: clamp(36px, 5vw, 60px);\n    line-height: 1.05;\n    letter-spacing: -0.03em;\n    color: var(--paper);\n    margin-bottom: 20px;\n  }\n\n  .cta-band h2 .gold { color: var(--gold); }\n\n  .cta-band p {\n    font-size: 19px;\n    line-height: 1.5;\n    color: rgba(255,255,255,0.7);\n    margin-bottom: 36px;\n    letter-spacing: -0.005em;\n  }\n\n  .cta-band-actions {\n    display: inline-flex;\n    gap: 12px;\n  }\n\n  .cta-band .btn-primary {\n    background: var(--paper);\n    color: var(--ink);\n  }\n\n  .cta-band .btn-primary:hover {\n    background: var(--royal-soft);\n  }\n\n  .cta-band .btn-ghost {\n    background: transparent;\n    color: var(--paper);\n    border-color: rgba(255,255,255,0.25);\n  }\n\n  .cta-band .btn-ghost:hover {\n    border-color: var(--paper);\n    background: rgba(255,255,255,0.05);\n  }\n\n  /* ============ FEATURES PAGE ============ */\n  .page-hero {\n    padding: 80px 0 60px;\n    text-align: center;\n  }\n\n  .page-hero h1 {\n    margin-bottom: 24px;\n    max-width: 920px;\n    margin-left: auto;\n    margin-right: auto;\n  }\n\n  .page-hero .lede {\n    max-width: 720px;\n    margin: 0 auto;\n  }\n\n  .features-page {\n    padding: 60px 0 100px;\n  }\n\n  .feature-section {\n    padding: 80px 0;\n  }\n\n  .feature-section + .feature-section {\n    border-top: 1px solid var(--hairline);\n  }\n\n  .feature-section-header {\n    display: grid;\n    grid-template-columns: 1fr 2.2fr;\n    gap: 80px;\n    margin-bottom: 56px;\n    align-items: start;\n  }\n\n  .feature-section-num {\n    font-family: var(--mono);\n    font-size: 13px;\n    color: var(--royal);\n    letter-spacing: 0.16em;\n    text-transform: uppercase;\n    padding-top: 14px;\n    border-top: 2px solid var(--royal);\n    display: inline-block;\n    font-weight: 600;\n  }\n\n  .feature-section-title {\n    font-weight: 700;\n    font-size: clamp(34px, 4vw, 48px);\n    line-height: 1.05;\n    letter-spacing: -0.03em;\n    color: var(--ink);\n    margin-bottom: 16px;\n  }\n\n  .feature-section-title .royal { color: var(--royal); }\n\n  .feature-section-sub {\n    font-size: 18px;\n    line-height: 1.55;\n    color: var(--slate);\n    max-width: 660px;\n    letter-spacing: -0.005em;\n  }\n\n  .feature-content {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 48px;\n    align-items: start;\n  }\n\n  .feature-content.reverse .feature-content-image {\n    order: 2;\n  }\n\n  .feature-content-image {\n    aspect-ratio: 4/5;\n    border-radius: 4px;\n    overflow: hidden;\n    background: var(--paper-3);\n  }\n\n  .feature-content-image img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  .feature-list {\n    list-style: none;\n    border-top: 1px solid var(--hairline);\n  }\n\n  .feature-list-item {\n    border-bottom: 1px solid var(--hairline);\n    padding: 24px 0;\n  }\n\n  .feature-list-item h4 {\n    font-size: 17px;\n    font-weight: 700;\n    letter-spacing: -0.02em;\n    color: var(--ink);\n    margin-bottom: 8px;\n  }\n\n  .feature-list-item p {\n    font-size: 15px;\n    line-height: 1.55;\n    color: var(--slate);\n    letter-spacing: -0.005em;\n  }\n\n  /* ============ PRICING PAGE ============ */\n  .pricing-hero {\n    padding: 80px 0 40px;\n    text-align: center;\n  }\n\n  .pricing-hero h1 {\n    max-width: 920px;\n    margin: 0 auto 24px;\n  }\n\n  .pricing-hero .lede {\n    max-width: 720px;\n    margin: 0 auto;\n  }\n\n  .gift-aid-banner {\n    padding: 60px 0 80px;\n  }\n\n  .gift-aid-banner-inner {\n    background: var(--ink);\n    color: var(--paper);\n    padding: 56px 64px;\n    border-radius: 12px;\n    position: relative;\n    overflow: hidden;\n    display: grid;\n    grid-template-columns: 1.4fr 1fr;\n    gap: 64px;\n    align-items: center;\n  }\n\n  .gift-aid-banner-inner::before {\n    content: '';\n    position: absolute;\n    top: -100px;\n    right: -100px;\n    width: 400px;\n    height: 400px;\n    background: radial-gradient(circle, rgba(212, 169, 58, 0.15) 0%, transparent 60%);\n  }\n\n  .gift-aid-banner-inner > * {\n    position: relative;\n    z-index: 2;\n  }\n\n  .gift-aid-banner-content h2 {\n    font-weight: 700;\n    font-size: clamp(28px, 3.4vw, 44px);\n    line-height: 1.05;\n    letter-spacing: -0.03em;\n    color: var(--paper);\n    margin-bottom: 16px;\n  }\n\n  .gift-aid-banner-content h2 .gold { color: var(--gold); }\n\n  .gift-aid-banner-content p {\n    font-size: 17px;\n    color: rgba(255,255,255,0.75);\n    margin-bottom: 32px;\n    letter-spacing: -0.005em;\n    line-height: 1.5;\n  }\n\n  .gift-aid-banner-stats {\n    display: grid;\n    grid-template-columns: 1fr;\n    gap: 16px;\n  }\n\n  .gift-aid-banner-stat {\n    background: rgba(255,255,255,0.05);\n    border: 1px solid rgba(255,255,255,0.1);\n    padding: 20px 24px;\n    border-radius: 8px;\n  }\n\n  .gift-aid-banner-stat-num {\n    font-weight: 700;\n    font-size: 32px;\n    color: var(--gold);\n    margin-bottom: 4px;\n    letter-spacing: -0.03em;\n    line-height: 1;\n  }\n\n  .gift-aid-banner-stat-label {\n    font-size: 14px;\n    color: rgba(255,255,255,0.75);\n    letter-spacing: -0.005em;\n  }\n\n  .pricing-tiers {\n    padding: 0 0 80px;\n  }\n\n  .pricing-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 16px;\n  }\n\n  .pricing-card {\n    background: var(--paper);\n    border: 1px solid var(--hairline);\n    border-radius: 12px;\n    padding: 32px 28px;\n    display: flex;\n    flex-direction: column;\n    transition: all 0.3s ease;\n  }\n\n  .pricing-card:hover {\n    border-color: var(--royal-line);\n    box-shadow: 0 20px 40px rgba(30, 64, 175, 0.06);\n  }\n\n  .pricing-card.featured {\n    background: var(--ink);\n    color: var(--paper);\n    border-color: var(--ink);\n    position: relative;\n  }\n\n  .pricing-card.featured::before {\n    content: 'MOST POPULAR';\n    position: absolute;\n    top: -12px;\n    left: 50%;\n    transform: translateX(-50%);\n    background: var(--gold);\n    color: var(--ink);\n    padding: 6px 14px;\n    border-radius: 999px;\n    font-size: 11px;\n    font-weight: 700;\n    letter-spacing: 0.12em;\n  }\n\n  .pricing-tag {\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 0.16em;\n    color: var(--slate-2);\n    margin-bottom: 16px;\n    font-weight: 600;\n  }\n\n  .pricing-card.featured .pricing-tag {\n    color: var(--gold);\n  }\n\n  .pricing-name {\n    font-size: 22px;\n    font-weight: 700;\n    letter-spacing: -0.02em;\n    margin-bottom: 12px;\n  }\n\n  .pricing-price {\n    font-weight: 700;\n    font-size: 38px;\n    line-height: 1;\n    margin: 8px 0 4px;\n    letter-spacing: -0.04em;\n    color: inherit;\n  }\n\n  .pricing-price .from {\n    font-size: 13px;\n    color: var(--slate-2);\n    font-weight: 600;\n    margin-right: 6px;\n    text-transform: uppercase;\n    letter-spacing: 0.1em;\n    vertical-align: middle;\n  }\n\n  .pricing-price .per {\n    font-size: 15px;\n    color: var(--slate-2);\n    font-weight: 500;\n    letter-spacing: -0.01em;\n  }\n\n  .pricing-card.featured .pricing-price .from,\n  .pricing-card.featured .pricing-price .per {\n    color: rgba(255,255,255,0.6);\n  }\n\n  .pricing-period {\n    font-size: 13px;\n    color: var(--slate-2);\n    margin-bottom: 20px;\n    letter-spacing: -0.005em;\n  }\n\n  .pricing-card.featured .pricing-period {\n    color: rgba(255,255,255,0.6);\n  }\n\n  .pricing-desc {\n    font-size: 14px;\n    line-height: 1.55;\n    color: var(--slate);\n    margin-bottom: 24px;\n    padding-bottom: 24px;\n    border-bottom: 1px solid var(--hairline);\n    letter-spacing: -0.005em;\n  }\n\n  .pricing-card.featured .pricing-desc {\n    color: rgba(255,255,255,0.75);\n    border-bottom-color: rgba(255,255,255,0.1);\n  }\n\n  .pricing-features {\n    list-style: none;\n    margin-bottom: 24px;\n    flex: 1;\n  }\n\n  .pricing-features-header {\n    font-size: 11px;\n    text-transform: uppercase;\n    letter-spacing: 0.14em;\n    color: var(--slate-2);\n    font-weight: 700;\n    padding: 4px 0 8px;\n    margin-bottom: 4px;\n  }\n\n  .pricing-card.featured .pricing-features-header {\n    color: var(--gold);\n  }\n\n  .pricing-card.featured .pricing-features-header + .pricing-features-header,\n  .pricing-features-header:not(:first-of-type) {\n    margin-top: 16px;\n  }\n\n  .pricing-features li {\n    font-size: 13px;\n    line-height: 1.5;\n    padding: 6px 0;\n    display: flex;\n    gap: 8px;\n    align-items: flex-start;\n    color: var(--ink);\n    letter-spacing: -0.005em;\n  }\n\n  .pricing-card.featured .pricing-features li {\n    color: rgba(255,255,255,0.85);\n  }\n\n  .pricing-features li svg {\n    color: var(--royal);\n    flex-shrink: 0;\n    margin-top: 4px;\n  }\n\n  .pricing-card.featured .pricing-features li svg {\n    color: var(--gold);\n  }\n\n  .pricing-cta {\n    width: 100%;\n    justify-content: center;\n  }\n\n  .pricing-card .pricing-cta {\n    background: var(--paper-3);\n    color: var(--ink);\n  }\n\n  .pricing-card .pricing-cta:hover {\n    background: var(--royal);\n    color: var(--paper);\n  }\n\n  .pricing-card.featured .pricing-cta {\n    background: var(--gold);\n    color: var(--ink);\n  }\n\n  .pricing-card.featured .pricing-cta:hover {\n    background: #C49A30;\n  }\n\n  /* FAQ */\n  .faq-section {\n    padding: 100px 0;\n    background: var(--paper-2);\n    border-top: 1px solid var(--hairline);\n  }\n\n  .faq-grid {\n    display: grid;\n    grid-template-columns: 1fr 1.5fr;\n    gap: 80px;\n    align-items: start;\n  }\n\n  .faq-list {\n    border-top: 1px solid var(--hairline);\n  }\n\n  .faq-item {\n    border-bottom: 1px solid var(--hairline);\n  }\n\n  .faq-q {\n    font-size: 17px;\n    font-weight: 700;\n    letter-spacing: -0.02em;\n    color: var(--ink);\n    cursor: pointer;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 16px;\n    padding: 24px 0;\n  }\n\n  .faq-q::after {\n    content: '+';\n    color: var(--royal);\n    font-size: 24px;\n    font-weight: 400;\n    transition: transform 0.3s ease;\n    flex-shrink: 0;\n  }\n\n  .faq-item.open .faq-q::after {\n    transform: rotate(45deg);\n  }\n\n  .faq-a {\n    font-size: 16px;\n    line-height: 1.6;\n    color: var(--slate);\n    max-height: 0;\n    overflow: hidden;\n    transition: max-height 0.4s ease, padding 0.3s ease;\n    letter-spacing: -0.005em;\n  }\n\n  .faq-item.open .faq-a {\n    max-height: 400px;\n    padding-bottom: 24px;\n  }\n\n  /* ============ CONTACT PAGE ============ */\n  .contact-hero {\n    padding: 80px 0 40px;\n  }\n\n  .contact-grid {\n    display: grid;\n    grid-template-columns: 1fr 1.2fr;\n    gap: 80px;\n    padding: 40px 0 100px;\n    align-items: start;\n  }\n\n  .contact-side h2 {\n    font-size: 32px;\n    font-weight: 700;\n    letter-spacing: -0.025em;\n    color: var(--ink);\n    margin-bottom: 16px;\n  }\n\n  .contact-side .body-text {\n    margin-bottom: 32px;\n  }\n\n  .contact-method {\n    display: flex;\n    gap: 16px;\n    padding: 20px 0;\n    border-bottom: 1px solid var(--hairline);\n    align-items: flex-start;\n  }\n\n  .contact-method:last-of-type {\n    border-bottom: none;\n  }\n\n  .contact-method-icon {\n    flex-shrink: 0;\n    width: 44px;\n    height: 44px;\n    background: var(--royal-soft);\n    border-radius: 10px;\n    color: var(--royal);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .contact-method-content {\n    flex: 1;\n  }\n\n  .contact-method-label {\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 0.14em;\n    color: var(--slate-2);\n    margin-bottom: 4px;\n    font-weight: 700;\n  }\n\n  .contact-method-value {\n    font-size: 17px;\n    font-weight: 700;\n    letter-spacing: -0.02em;\n    color: var(--ink);\n    margin-bottom: 4px;\n  }\n\n  .contact-method-detail {\n    font-size: 14px;\n    color: var(--slate);\n    letter-spacing: -0.005em;\n  }\n\n  .contact-form {\n    background: var(--paper-2);\n    border: 1px solid var(--hairline);\n    border-radius: 12px;\n    padding: 48px 44px;\n  }\n\n  .form-eyebrow {\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 0.16em;\n    color: var(--royal);\n    font-weight: 700;\n    margin-bottom: 12px;\n  }\n\n  .form-title {\n    font-size: 28px;\n    font-weight: 700;\n    letter-spacing: -0.025em;\n    color: var(--ink);\n    margin-bottom: 32px;\n  }\n\n  .form-row {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin-bottom: 16px;\n  }\n\n  .form-field {\n    margin-bottom: 16px;\n  }\n\n  .form-label {\n    display: block;\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--ink);\n    margin-bottom: 8px;\n    letter-spacing: -0.005em;\n  }\n\n  .form-input, .form-select, .form-textarea {\n    width: 100%;\n    padding: 14px 16px;\n    background: var(--paper);\n    border: 1px solid var(--hairline);\n    font-family: var(--sans);\n    font-size: 15px;\n    color: var(--ink);\n    transition: border-color 0.2s ease;\n    border-radius: 8px;\n  }\n\n  .form-input:focus, .form-select:focus, .form-textarea:focus {\n    outline: none;\n    border-color: var(--royal);\n  }\n\n  .form-textarea {\n    resize: vertical;\n    min-height: 120px;\n    line-height: 1.5;\n  }\n\n  .form-help {\n    font-size: 13px;\n    color: var(--slate-2);\n    margin-top: 6px;\n    letter-spacing: -0.005em;\n  }\n\n  .form-submit {\n    margin-top: 8px;\n    width: 100%;\n    justify-content: center;\n    padding: 16px 24px;\n  }\n\n  .form-foot {\n    margin-top: 16px;\n    text-align: center;\n    font-size: 13px;\n    color: var(--slate-2);\n    letter-spacing: -0.005em;\n  }\n\n  /* ============ Footer ============ */\n  .footer {\n    background: var(--ink);\n    color: var(--paper);\n    padding: 80px 0 32px;\n  }\n\n  .footer-grid {\n    display: grid;\n    grid-template-columns: 2fr 1fr 1fr 1fr;\n    gap: 80px;\n    margin-bottom: 56px;\n  }\n\n  .footer-brand img {\n    height: 38px;\n    margin-bottom: 24px;\n    filter: brightness(0) invert(1);\n  }\n\n  .footer-tag {\n    font-size: 15px;\n    line-height: 1.55;\n    color: rgba(255,255,255,0.65);\n    max-width: 320px;\n    letter-spacing: -0.005em;\n  }\n\n  .footer-col h4 {\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 0.18em;\n    color: var(--gold);\n    font-weight: 700;\n    margin-bottom: 20px;\n  }\n\n  .footer-col ul {\n    list-style: none;\n  }\n\n  .footer-col li {\n    margin-bottom: 12px;\n  }\n\n  .footer-col a {\n    font-size: 15px;\n    color: rgba(255,255,255,0.7);\n    transition: color 0.2s ease;\n    cursor: pointer;\n    letter-spacing: -0.005em;\n  }\n\n  .footer-col a:hover { color: var(--paper); }\n\n  .footer-base {\n    padding-top: 32px;\n    border-top: 1px solid rgba(255,255,255,0.08);\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    font-size: 13px;\n    color: rgba(255,255,255,0.5);\n    letter-spacing: -0.005em;\n  }\n\n  .footer-base-links {\n    display: flex;\n    gap: 24px;\n  }\n\n  .footer-base-links a,\n  .footer-base-links button {\n    color: rgba(255,255,255,0.5);\n    text-decoration: none;\n    transition: color 0.2s ease;\n  }\n\n  .footer-base-links button {\n    border: 0;\n    padding: 0;\n    background: transparent;\n    font: inherit;\n    cursor: pointer;\n  }\n\n  .footer-base-links a:hover,\n  .footer-base-links button:hover {\n    color: var(--paper);\n  }\n\n  /* Reveal */\n  .reveal {\n    opacity: 0;\n    transform: translateY(20px);\n    transition: opacity 0.7s ease, transform 0.7s ease;\n  }\n  .reveal.in {\n    opacity: 1;\n    transform: translateY(0);\n  }\n\n  /* ============ Responsive ============ */\n  @media (max-width: 1024px) {\n    .pricing-grid { grid-template-columns: repeat(2, 1fr); }\n    .layers-grid { grid-template-columns: 1fr; }\n    .gift-aid-grid, .feature-block-grid, .feature-content { grid-template-columns: 1fr; gap: 48px; }\n    .feature-section-header { grid-template-columns: 1fr; gap: 32px; }\n    .replaces-grid { grid-template-columns: 1fr; }\n    .gift-aid-banner-inner { grid-template-columns: 1fr; gap: 40px; padding: 40px; }\n    .footer-grid { grid-template-columns: 1fr 1fr; gap: 40px; }\n    .container, .container-narrow, .nav-inner, .trust-inner { padding-left: 32px; padding-right: 32px; }\n    .trust-inner { grid-template-columns: 1fr; }\n    .trust-items { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n  }\n\n  @media (max-width: 768px) {\n    .nav-inner { gap: 12px; }\n    .nav-logo img { height: 34px; }\n    .nav-links { display: none; }\n    .nav-cta { gap: 8px; }\n    .nav-cta .btn { padding: 12px 18px; }\n    .nav-cta .btn-ghost { display: none; }\n    .mobile-nav-toggle { display: inline-flex; }\n    .nav.mobile-open .mobile-menu { display: block; }\n    .hero-grid, .province-grid, .contact-grid, .faq-grid {\n      grid-template-columns: 1fr;\n      gap: 48px;\n    }\n    .hero-image {\n      width: 100%;\n      min-height: 0;\n      margin-left: 0;\n    }\n    .pricing-grid { grid-template-columns: 1fr; }\n    .footer-grid { grid-template-columns: 1fr; }\n    .footer-base { flex-direction: column; gap: 16px; }\n    .container, .container-narrow, .nav-inner, .trust-inner { padding-left: 20px; padding-right: 20px; }\n    .trust { padding: 44px 0; }\n    .trust-items { grid-template-columns: 1fr; }\n    .trust-item { min-height: 104px; }\n    .contact-form { padding: 32px 24px; }\n    .form-row { grid-template-columns: 1fr; }\n    .feature-block.reverse .feature-block-grid > div:first-child { order: 0; }\n    .feature-content.reverse .feature-content-image { order: 0; }\n  }";
const SITE_HTML = "<!-- ============ NAVIGATION ============ -->\n<nav class=\"nav\">\n  <div class=\"nav-inner\">\n    <a class=\"nav-logo\" data-route=\"home\">\n      <img src=\"data:image/png;base64,\" alt=\"LodgePay\">\n    </a>\n    <div class=\"nav-links\">\n      <a class=\"nav-link active\" data-route=\"home\">Home</a>\n      <a class=\"nav-link\" data-route=\"features\">Features</a>\n      <a class=\"nav-link\" data-route=\"pricing\">Pricing</a>\n      <a class=\"nav-link\" data-route=\"contact\">Contact</a>\n    </div>\n    <div class=\"nav-cta\">\n      <a class=\"btn btn-ghost\" data-route=\"contact\">Book a demo</a>\n      <a class=\"btn btn-primary\" href=\"/login\">Log in</a>\n      <button class=\"mobile-nav-toggle\" type=\"button\" aria-label=\"Open menu\" aria-expanded=\"false\">\n        <svg class=\"icon-menu\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\"/><line x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\"/><line x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\"/></svg>\n        <svg class=\"icon-close\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n  </div>\n  <div class=\"mobile-menu\">\n    <div class=\"mobile-menu-inner\">\n      <a class=\"mobile-nav-link nav-link active\" data-route=\"home\">Home</a>\n      <a class=\"mobile-nav-link nav-link\" data-route=\"features\">Features</a>\n      <a class=\"mobile-nav-link nav-link\" data-route=\"pricing\">Pricing</a>\n      <a class=\"mobile-nav-link nav-link\" data-route=\"contact\">Contact</a>\n      <a class=\"btn btn-ghost\" data-route=\"contact\">Book a demo</a>\n    </div>\n  </div>\n</nav>\n\n<!-- ============ HOMEPAGE ============ -->\n<main class=\"page active\" data-page=\"home\">\n\n  <!-- Hero -->\n  <section class=\"hero\">\n    <div class=\"container\">\n      <div class=\"hero-grid\">\n        <div>\n          <div class=\"eyebrow\">For Craft Lodges, Provinces &amp; Halls</div>\n          <h1>Your summons, your books, and your candidates finally one record.</h1>\n          <p class=\"hero-sub\">LodgePay is the lodge operating system. Website, member portal, meetings, dues, charity with Gift Aid, candidate pipeline, Almoner welfare, and reporting. Built around the way officers already serve the lodge.</p>\n          <div class=\"hero-actions\">\n            <a class=\"btn btn-primary btn-large\" data-route=\"contact\">Book a demo</a>\n            <a class=\"btn btn-ghost btn-large\" data-route=\"features\">See what is included</a>\n          </div>\n          <div class=\"hero-meta\">\n            <div class=\"hero-meta-item\">\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n              No setup fee\n            </div>\n            <div class=\"hero-meta-item\">\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n              Officer training included\n            </div>\n            <div class=\"hero-meta-item\">\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n              14-day sandbox\n            </div>\n          </div>\n        </div>\n        <div class=\"hero-image\">\n          <img src=\"/marketing/hero-leaders.png\" alt=\"Four lodge leaders in formal attire in a wood-paneled temple room\">\n          <span class=\"hero-image-ring\"></span>\n          <div class=\"hero-badge\"><span class=\"hero-badge-check\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M16.7 5.3a1 1 0 0 1 0 1.4l-7.25 7.32a1 1 0 0 1-1.42 0l-3.75-3.75a1 1 0 1 1 1.42-1.42l3.04 3.05 6.54-6.6a1 1 0 0 1 1.42 0Z\"></path></svg></span><span class=\"hero-badge-text\"><strong>One shared record</strong><em>Secretary &middot; Treasurer &middot; Almoner</em></span></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Trust band -->\n  <section class=\"trust\">\n    <div class=\"trust-inner\">\n      <div class=\"trust-copy\">\n        <div class=\"trust-label\">Built for</div>\n        <h2>Every lodge body, from one Craft lodge to a Province.</h2>\n        <p>Pick the work you need today. Websites, summons, dues, charity and member communications all stay in one record.</p>\n      </div>\n      <div class=\"trust-items\" aria-label=\"LodgePay audiences\">\n        <div class=\"trust-item\"><span class=\"trust-icon\">01</span><span>Craft Lodges</span></div>\n        <div class=\"trust-item\"><span class=\"trust-icon\">02</span><span>Royal Arch</span></div>\n        <div class=\"trust-item\"><span class=\"trust-icon\">03</span><span>Mark Lodges</span></div>\n        <div class=\"trust-item\"><span class=\"trust-icon\">04</span><span>Provinces &amp; Districts</span></div>\n        <div class=\"trust-item\"><span class=\"trust-icon\">05</span><span>Hall Groups</span></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Three layers -->\n  <section class=\"layers\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <div class=\"eyebrow\">The Platform</div>\n        <h2 class=\"display\">One platform. Every officer covered.</h2>\n        <p class=\"lede\" style=\"margin-top: 20px;\">LodgePay lets each lodge buy what it needs today and grow into the rest. Each part maps to a real officer's work.</p>\n      </div>\n\n      <div class=\"layers-grid\">\n        <div class=\"layer-card\">\n          <div class=\"layer-card-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Lodge operations\">\n          </div>\n          <div class=\"layer-card-body\">\n            <h3 class=\"layer-card-title\">The Lodge Operating System</h3>\n            <p class=\"layer-card-sub\">Everything an officer team needs to run the lodge, take payments, and reclaim every penny of Gift Aid.</p>\n            <ul class=\"layer-card-features\">\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Lodge website &amp; member portal</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Meetings, summons &amp; RSVPs</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Dues &amp; payments via Mooov</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Gift Aid &amp; GASDS at source</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Treasurer reconciliation</li>\n            </ul>\n            <div class=\"layer-card-buyer\">\n              Bought by\n              <strong>Secretary &amp; Treasurer</strong>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"layer-card\">\n          <div class=\"layer-card-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Lodge intelligence\">\n          </div>\n          <div class=\"layer-card-body\">\n            <h3 class=\"layer-card-title\">Lodge Intelligence</h3>\n            <p class=\"layer-card-sub\">AI that lifts the work off officer shoulders. Members-at-risk, post-meeting summaries, summons drafting, and the audit trail.</p>\n            <ul class=\"layer-card-features\">\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>AI assistant for drafting</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Members-at-risk insights</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Post-meeting summaries</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Data quality &amp; consent checks</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Candidate pipeline with AI</li>\n            </ul>\n            <div class=\"layer-card-buyer\">\n              Bought by\n              <strong>Master &amp; Mentor</strong>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"layer-card\">\n          <div class=\"layer-card-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Provincial platform\">\n          </div>\n          <div class=\"layer-card-body\">\n            <h3 class=\"layer-card-title\">The Provincial Platform</h3>\n            <p class=\"layer-card-sub\">Province-wide rollout, central oversight, annual returns, and the operator console for portfolio visibility.</p>\n            <ul class=\"layer-card-features\">\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Operator console &amp; dashboards</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Annual returns CSV (one click)</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Bulk lodge operations</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Central billing across lodges</li>\n              <li><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Migration &amp; named support</li>\n            </ul>\n            <div class=\"layer-card-buyer\">\n              Bought by\n              <strong>Provincial Grand Master</strong>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Gift Aid -->\n  <section class=\"gift-aid\">\n    <div class=\"container gift-aid-inner\">\n      <div class=\"gift-aid-grid\">\n        <div class=\"gift-aid-image\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Treasurer reconciliation\">\n        </div>\n        <div class=\"gift-aid-content\">\n          <div class=\"eyebrow\">For the Treasurer</div>\n          <h2>Most lodges can recover <span class=\"gold\">£1,000+ a year in missed Gift Aid.</span></h2>\n          <p>LodgePay helps find it automatically: on dues, at the festive board, and on every donation. Add GASDS cash collections and the value can go much further.</p>\n          <div class=\"gift-aid-stats\">\n            <div>\n              <div class=\"gift-aid-stat-num\">£225</div>\n              <div class=\"gift-aid-stat-label\">From dues, itemised charity portion across 30 members</div>\n            </div>\n            <div>\n              <div class=\"gift-aid-stat-num\">£900</div>\n              <div class=\"gift-aid-stat-label\">From the festive board, eight meetings a year</div>\n            </div>\n            <div>\n              <div class=\"gift-aid-stat-num\">+ GASDS</div>\n              <div class=\"gift-aid-stat-label\">Up to £8,000/year on cash collections</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Feature blocks -->\n  <section class=\"feature-block\">\n    <div class=\"container\">\n      <div class=\"feature-block-grid\">\n        <div>\n          <div class=\"eyebrow\">Public website &amp; member portal</div>\n          <h2 class=\"display\">A lodge website that does more than tell the story.</h2>\n          <p class=\"body-text\">Visitors find the lodge, members manage their commitments, officers update content without calling a webmaster. Each lodge keeps its own identity, content, and pace.</p>\n          <div class=\"feature-pills\">\n            <span class=\"feature-pill\">Per-lodge branding</span>\n            <span class=\"feature-pill\">AI-assisted drafting</span>\n            <span class=\"feature-pill\">Installable PWA</span>\n            <span class=\"feature-pill\">Digital lodge card</span>\n            <span class=\"feature-pill\">SEO ready</span>\n          </div>\n          <a class=\"btn btn-ghost\" data-route=\"features\">Explore the platform →</a>\n        </div>\n        <div class=\"feature-block-image\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Lodge website on phone\">\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"feature-block reverse\" style=\"background: var(--paper-2);\">\n    <div class=\"container\">\n      <div class=\"feature-block-grid\">\n        <div>\n          <div class=\"eyebrow\">Meetings, summons &amp; hospitality</div>\n          <h2 class=\"display\">From summons draft to attendance roll, in one record.</h2>\n          <p class=\"body-text\">RSVPs that capture what catering actually needs. Ceremony versus dining. Guests. Dietary notes. Attendance. The evening runs from one source of truth, not three different chats.</p>\n          <div class=\"feature-pills\">\n            <span class=\"feature-pill\">Summons workflow</span>\n            <span class=\"feature-pill\">Print &amp; email parity</span>\n            <span class=\"feature-pill\">Dietary by member</span>\n            <span class=\"feature-pill\">Steward counts</span>\n            <span class=\"feature-pill\">Attendance to record</span>\n          </div>\n          <a class=\"btn btn-ghost\" data-route=\"features\">Explore the platform →</a>\n        </div>\n        <div class=\"feature-block-image\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Lodge meeting\">\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"feature-block\">\n    <div class=\"container\">\n      <div class=\"feature-block-grid\">\n        <div>\n          <div class=\"eyebrow\">Charity, candidates &amp; welfare</div>\n          <h2 class=\"display\">From first enquiry to fortieth year, with care visible at every stage.</h2>\n          <p class=\"body-text\">A pipeline that doesn't lose candidates. Charity campaigns with full Gift Aid attribution. Welfare cases with discretion-aware permissions. The slow, considered work of the lodge, treated with the seriousness it deserves.</p>\n          <div class=\"feature-pills\">\n            <span class=\"feature-pill\">Candidate CRM</span>\n            <span class=\"feature-pill\">AI next-action</span>\n            <span class=\"feature-pill\">Almoner welfare</span>\n            <span class=\"feature-pill\">Mentor sign-off</span>\n            <span class=\"feature-pill\">Donor history</span>\n          </div>\n          <a class=\"btn btn-ghost\" data-route=\"features\">Explore the platform →</a>\n        </div>\n        <div class=\"feature-block-image\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Lodge candidates\">\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Replaces -->\n  <section class=\"replaces\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <div class=\"eyebrow\">What replaces what</div>\n        <h2 class=\"display\">When LodgePay arrives, the lodge leaves behind.</h2>\n      </div>\n\n      <div class=\"replaces-grid\">\n        <div class=\"replaces-card\">\n          <div class=\"replaces-card-icon\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"9\" x2=\"21\" y2=\"9\"/><line x1=\"9\" y1=\"21\" x2=\"9\" y2=\"9\"/></svg>\n          </div>\n          <h3>The Treasurer's spreadsheet</h3>\n          <p>The parallel ledger that tracks what the bank didn't. The reconciliation that takes a Sunday afternoon. The dues spreadsheet emailed back and forth. Replaced with one ledger that matches the bank.</p>\n        </div>\n        <div class=\"replaces-card\">\n          <div class=\"replaces-card-icon\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>\n          </div>\n          <h3>The summons WhatsApp group</h3>\n          <p>The thread where dietary requirements get lost. The replies that arrive at midnight. The chase the night before the festive board. RSVPs and dietary notes now live next to the meeting record.</p>\n        </div>\n        <div class=\"replaces-card\">\n          <div class=\"replaces-card-icon\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\n          </div>\n          <h3>The Almoner's notebook</h3>\n          <p>Pastoral care belongs in software designed for it, not a paper notebook in a drawer. Welfare cases with discretion-aware permissions, so the right people see what they need to help.</p>\n        </div>\n        <div class=\"replaces-card\">\n          <div class=\"replaces-card-icon\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n          </div>\n          <h3>The candidate Sunday email</h3>\n          <p>\"Where are we with that candidate?\" answered with \"I'll have to check.\" A pipeline that shows every candidate, every stage, every owner, every next action.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Province -->\n  <section class=\"province\">\n    <div class=\"container\">\n      <div class=\"province-grid\">\n        <div class=\"province-image\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Provincial team\">\n        </div>\n        <div>\n          <div class=\"eyebrow\">For Provinces &amp; Districts</div>\n          <h2 class=\"display\" style=\"margin-bottom: 24px;\">One platform for the Province. Each lodge still its own home.</h2>\n          <p class=\"body-text\" style=\"margin-bottom: 24px;\">Roll LodgePay across the Province with per-lodge sites, books, and members. Central staff retain billing, support, integrations, and portfolio reporting.</p>\n          <p class=\"body-text\" style=\"margin-bottom: 32px;\">Province-level dashboards show dues posture, summons compliance, RSVP coverage, and charity performance across every lodge. Annual returns export in one click. Migration planning included.</p>\n          <a class=\"btn btn-primary btn-large\" data-route=\"contact\">Speak to us about a Province-wide rollout</a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Quote -->\n  <section class=\"quote-section\">\n    <div class=\"container\">\n      <div class=\"quote-block\">\n        <div class=\"quote-mark\">\"</div>\n        <p class=\"quote-text\">A lodge is not a website. It is brethren meeting on the level. LodgePay exists so the labour around that meeting, the charity after it, and the care between meetings does not exhaust the brethren who already give their time without fee or reward.</p>\n        <div class=\"quote-attr\">LodgePay · Principles we build toward</div>\n      </div>\n    </div>\n  </section>\n\n  <!-- CTA -->\n  <section class=\"cta-band\">\n    <div class=\"container cta-band-inner\">\n      <h2>Find out what your lodge has been <span class=\"gold\">leaving on the table.</span></h2>\n      <p>A 30-minute walkthrough, free, no commitment. We'll show you the Gift Aid your lodge could be reclaiming, with your own membership numbers.</p>\n      <div class=\"cta-band-actions\">\n        <a class=\"btn btn-primary btn-large\" data-route=\"contact\">Book the walkthrough</a>\n        <a class=\"btn btn-ghost btn-large\" data-route=\"pricing\">View pricing</a>\n      </div>\n    </div>\n  </section>\n\n</main>\n\n<!-- ============ FEATURES PAGE ============ -->\n<main class=\"page\" data-page=\"features\">\n\n  <section class=\"page-hero\">\n    <div class=\"container-narrow\">\n      <div class=\"eyebrow\">Features</div>\n      <h1 class=\"display\">Everything a lodge actually does, in one record.</h1>\n      <p class=\"lede\" style=\"margin-top: 20px;\">Public site, member portal, meetings, summons, dues, payments, charity with Gift Aid, candidate pipeline, Almoner welfare, AI assistant, full reporting suite, and provincial oversight. Built around the way officers already serve the lodge.</p>\n    </div>\n  </section>\n\n  <section class=\"features-page\">\n    <div class=\"container\">\n\n      <!-- I. Site -->\n      <section class=\"feature-section\">\n        <div class=\"feature-section-header\">\n          <div class=\"feature-section-num\">I · Online presence</div>\n          <div>\n            <h2 class=\"feature-section-title\">A lodge website that does more than tell <span class=\"royal\">the story.</span></h2>\n            <p class=\"feature-section-sub\">Visitors find the lodge, members manage their commitments, officers update content without calling a webmaster.</p>\n          </div>\n        </div>\n        <div class=\"feature-content\">\n          <div class=\"feature-content-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Lodge website\">\n          </div>\n          <ul class=\"feature-list\">\n            <li class=\"feature-list-item\"><h4>Branded lodge website</h4><p>Public site with the lodge name, history, officers, charity story, and meeting calendar. Per-lodge branding, colours, and tagline.</p></li>\n            <li class=\"feature-list-item\"><h4>Section-based editor</h4><p>Officers update content directly. Visual builder for the home page and main sections. AI-assisted drafting for fast first drafts.</p></li>\n            <li class=\"feature-list-item\"><h4>Member portal</h4><p>Every member signs in to a dashboard showing upcoming events, summons, dues, donations, payments, and digital lodge card.</p></li>\n            <li class=\"feature-list-item\"><h4>Installable to phones</h4><p>Progressive web app the lodge installs to a member's home screen like a native app. Works offline for the most-used screens.</p></li>\n            <li class=\"feature-list-item\"><h4>Public events &amp; charity</h4><p>RSVP-able events on the public site. Charity campaign pages with progress tracking and donation flow tied to Gift Aid.</p></li>\n            <li class=\"feature-list-item\"><h4>Enquiry capture</h4><p>Contact forms feed straight into the candidate pipeline. No copying email addresses into spreadsheets.</p></li>\n          </ul>\n        </div>\n      </section>\n\n      <!-- II. Meetings -->\n      <section class=\"feature-section\">\n        <div class=\"feature-section-header\">\n          <div class=\"feature-section-num\">II · The Secretary's domain</div>\n          <div>\n            <h2 class=\"feature-section-title\">From summons draft to attendance roll, <span class=\"royal\">in one record.</span></h2>\n            <p class=\"feature-section-sub\">Meetings are the spine of the lodge year. LodgePay treats them as first-class records, not generic calendar entries.</p>\n          </div>\n        </div>\n        <div class=\"feature-content reverse\">\n          <div class=\"feature-content-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Lodge meeting\">\n          </div>\n          <ul class=\"feature-list\">\n            <li class=\"feature-list-item\"><h4>Meeting records</h4><p>Every meeting is a record with date, location, ceremony type, agenda, and attendance. Distinct from generic events because it carries operational weight.</p></li>\n            <li class=\"feature-list-item\"><h4>Summons workflow</h4><p>View, edit, print, and send the summons from one screen. Send history preserved. Tokenised public links for members.</p></li>\n            <li class=\"feature-list-item\"><h4>RSVPs that match lodge life</h4><p>Ceremony attendance vs dining captured separately. Guests, dietary notes, payment status, apologies on one event.</p></li>\n            <li class=\"feature-list-item\"><h4>Dietary tracking by member</h4><p>Members maintain dietary preferences once. The system carries them forward to every event RSVP.</p></li>\n            <li class=\"feature-list-item\"><h4>Steward counts</h4><p>Real-time confirmed counts for the Steward, with cut-off dates and chase reminders. No more spreadsheets the night before.</p></li>\n            <li class=\"feature-list-item\"><h4>Attendance to record</h4><p>Attendance feeds the member's history. Years of data without anyone typing it in.</p></li>\n          </ul>\n        </div>\n      </section>\n\n      <!-- III. Payments -->\n      <section class=\"feature-section\">\n        <div class=\"feature-section-header\">\n          <div class=\"feature-section-num\">III · The Treasurer's domain</div>\n          <div>\n            <h2 class=\"feature-section-title\">A ledger that matches the bank, <span class=\"royal\">with Gift Aid found automatically.</span></h2>\n            <p class=\"feature-section-sub\">This is where most lodges leak money, time, and accuracy. LodgePay closes the gaps and surfaces every penny of Gift Aid the lodge is owed.</p>\n          </div>\n        </div>\n        <div class=\"feature-content\">\n          <div class=\"feature-content-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Treasurer's desk\">\n          </div>\n          <ul class=\"feature-list\">\n            <li class=\"feature-list-item\"><h4>Mooov payment orchestration</h4><p>Payments routed through Mooov's PSP network. Resilience, choice, and one consistent ledger across providers.</p></li>\n            <li class=\"feature-list-item\"><h4>Webhook-verified status</h4><p>Payments don't get stuck pending. Webhook reconciliation across providers means the ledger matches the bank.</p></li>\n            <li class=\"feature-list-item\"><h4>Dues with charity portion</h4><p>Annual subs split into membership and charitable portions. Gift Aid applies automatically to the eligible part.</p></li>\n            <li class=\"feature-list-item\"><h4>Bulk dues runs &amp; reminders</h4><p>Schedule the annual run for every member. Automated reminders on a sensible cadence, escalation for the genuinely late.</p></li>\n            <li class=\"feature-list-item\"><h4>Festive board collections</h4><p>The alms collection at the meeting, attributed to members, with Gift Aid on those with declarations.</p></li>\n            <li class=\"feature-list-item\"><h4>GASDS cash tracking</h4><p>Track cash collections, surface them as Small Donations Scheme eligible. Up to £8,000/year reclaimed without declarations.</p></li>\n            <li class=\"feature-list-item\"><h4>Bank import &amp; reconciliation</h4><p>Import CSV from the lodge bank. LodgePay matches to payment intents and surfaces unmatched. Month-end is confirmation, not archaeology.</p></li>\n            <li class=\"feature-list-item\"><h4>HMRC-ready exports</h4><p>Gift Aid claim flows and GASDS annual allowance reporting. The lodge files the claim, we surface what's owed.</p></li>\n          </ul>\n        </div>\n      </section>\n\n      <!-- IV. Membership -->\n      <section class=\"feature-section\">\n        <div class=\"feature-section-header\">\n          <div class=\"feature-section-num\">IV · Membership, charity &amp; welfare</div>\n          <div>\n            <h2 class=\"feature-section-title\">From first enquiry to fortieth year, <span class=\"royal\">with care visible.</span></h2>\n            <p class=\"feature-section-sub\">The work that shapes the lodge isn't transactional. It's bringing in new members, running the charity, and looking after the brethren who need it.</p>\n          </div>\n        </div>\n        <div class=\"feature-content reverse\">\n          <div class=\"feature-content-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Charity and welfare\">\n          </div>\n          <ul class=\"feature-list\">\n            <li class=\"feature-list-item\"><h4>Candidate CRM</h4><p>Managed journey with stages: enquiry, interview, proposer, ballot, initiation. Every candidate is a record with owner and activity log.</p></li>\n            <li class=\"feature-list-item\"><h4>Pipeline board</h4><p>Kanban board showing every candidate by stage. Workload obvious at a glance. Drag to advance.</p></li>\n            <li class=\"feature-list-item\"><h4>Charity campaigns</h4><p>Run a campaign for the Festival or a one-off appeal. Each has a target, story, progress tracker, and donor history.</p></li>\n            <li class=\"feature-list-item\"><h4>Donor history per member</h4><p>Every member's giving history preserved. Charity Steward sees who gave what, when, with full Gift Aid status.</p></li>\n            <li class=\"feature-list-item\"><h4>Welfare cases</h4><p>Each case is a record: the member, the situation, the support, the people involved. Sensitive content with proper access control.</p></li>\n            <li class=\"feature-list-item\"><h4>Discretion-aware permissions</h4><p>The Almoner sees full case detail. The Master sees a case exists. The wider lodge sees nothing. Pastoral care meets GDPR.</p></li>\n            <li class=\"feature-list-item\"><h4>Mentor assignment</h4><p>Mentor assigned to each candidate and new member. Contact history, progression tracking, sign-off ready for Grand Lodge.</p></li>\n            <li class=\"feature-list-item\"><h4>Communications hub</h4><p>Templates, newsletters, audience selection, status tracking. Merge tags for personalised lodge emails.</p></li>\n          </ul>\n        </div>\n      </section>\n\n      <!-- V. AI / Reporting -->\n      <section class=\"feature-section\">\n        <div class=\"feature-section-header\">\n          <div class=\"feature-section-num\">V · AI, reporting &amp; oversight</div>\n          <div>\n            <h2 class=\"feature-section-title\">Reports that answer the room, <span class=\"royal\">before it asks.</span></h2>\n            <p class=\"feature-section-sub\">Lodge committee meetings and AGMs run on numbers. LodgePay produces the briefings. The AI does the drafting.</p>\n          </div>\n        </div>\n        <div class=\"feature-content\">\n          <div class=\"feature-content-image\">\n            <img src=\"data:image/jpeg;base64,\" alt=\"Reporting\">\n          </div>\n          <ul class=\"feature-list\">\n            <li class=\"feature-list-item\"><h4>AI assistant</h4><p>Drafts summons, suggests next actions, summarises post-meeting notes. The Master's gavel stays where it belongs.</p></li>\n            <li class=\"feature-list-item\"><h4>Members-at-risk insights</h4><p>The assistant flags brethren drifting from attendance, dues, or engagement. Mentor outreach before they resign.</p></li>\n            <li class=\"feature-list-item\"><h4>Post-meeting summaries</h4><p>Generated automatically from the meeting record, ready for circulation or the next agenda.</p></li>\n            <li class=\"feature-list-item\"><h4>Data quality checks</h4><p>The assistant surfaces missing dietary, addresses, consent gaps, expired declarations. Clean records, automatically.</p></li>\n            <li class=\"feature-list-item\"><h4>Treasurer &amp; Charity reports</h4><p>Income breakdown, dues posture, reconciliation status, Gift Aid reclaimable. Every line tied to its payment intent.</p></li>\n            <li class=\"feature-list-item\"><h4>Province annual returns</h4><p>One-click CSV export across every lodge in the Province. The most painful annual task, made trivial.</p></li>\n            <li class=\"feature-list-item\"><h4>Audit trail</h4><p>Every sensitive action logged: who, what, when, which record. Export-ready for compliance reviews.</p></li>\n            <li class=\"feature-list-item\"><h4>Role-based access &amp; MFA</h4><p>Nine officer roles with granular permissions. MFA for admin users. PCI scope managed by Mooov and providers.</p></li>\n          </ul>\n        </div>\n      </section>\n\n    </div>\n  </section>\n\n  <!-- CTA -->\n  <section class=\"cta-band\">\n    <div class=\"container cta-band-inner\">\n      <h2>See it run on <span class=\"gold\">your lodge.</span></h2>\n      <p>We set up a sandbox with your lodge's branding so officers see exactly how it would work before deciding.</p>\n      <div class=\"cta-band-actions\">\n        <a class=\"btn btn-primary btn-large\" data-route=\"contact\">Book the walkthrough</a>\n      </div>\n    </div>\n  </section>\n\n</main>\n\n<!-- ============ PRICING PAGE ============ -->\n<main class=\"page\" data-page=\"pricing\">\n\n  <section class=\"pricing-hero\">\n    <div class=\"container-narrow\">\n      <div class=\"eyebrow\">Pricing</div>\n      <h1 class=\"display\">One year of LodgePay pays for itself.</h1>\n      <p class=\"lede\" style=\"margin-top: 20px;\">Most lodges leave £1,000 or more in Gift Aid unclaimed every year. LodgePay finds it automatically, on dues, at the festive board, and on every donation.</p>\n    </div>\n  </section>\n\n  <!-- Gift Aid banner -->\n  <section class=\"gift-aid-banner\">\n    <div class=\"container\">\n      <div class=\"gift-aid-banner-inner\">\n        <div class=\"gift-aid-banner-content\">\n          <h2>A typical 30-member lodge reclaims <span class=\"gold\">£1,125 a year.</span></h2>\n          <p>Without filling in a single form. The platform pays for itself before we factor in the time it saves.</p>\n        </div>\n        <div class=\"gift-aid-banner-stats\">\n          <div class=\"gift-aid-banner-stat\">\n            <div class=\"gift-aid-banner-stat-num\">£225</div>\n            <div class=\"gift-aid-banner-stat-label\">From dues, itemised charity portion</div>\n          </div>\n          <div class=\"gift-aid-banner-stat\">\n            <div class=\"gift-aid-banner-stat-num\">£900</div>\n            <div class=\"gift-aid-banner-stat-label\">From the festive board, eight meetings</div>\n          </div>\n          <div class=\"gift-aid-banner-stat\">\n            <div class=\"gift-aid-banner-stat-num\">+ GASDS</div>\n            <div class=\"gift-aid-banner-stat-label\">Up to £8,000/year on cash gifts</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Pricing tiers -->\n  <section class=\"pricing-tiers\">\n    <div class=\"container\">\n      <div class=\"pricing-grid\">\n        <div class=\"pricing-card\">\n          <div class=\"pricing-tag\">Single Lodge</div>\n          <div class=\"pricing-name\">Essentials</div>\n          <div class=\"pricing-price\"><span class=\"from\">From</span>£149<span class=\"per\">/mo</span></div>\n          <div class=\"pricing-period\">billed annually · or £169 monthly</div>\n          <div class=\"pricing-desc\">Everything an officer team needs to run the lodge, take payments, and reclaim every penny of Gift Aid.</div>\n\n          <div class=\"pricing-features-header\">The lodge, online</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Public lodge website</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Member portal &amp; PWA</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Digital lodge card</li>\n          </ul>\n\n          <div class=\"pricing-features-header\">The money, handled</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Mooov payment orchestration</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Bank import &amp; reconciliation</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Treasurer report</li>\n          </ul>\n\n          <div class=\"pricing-features-header\">Gift Aid, everywhere</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Gift Aid on dues &amp; donations</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>GASDS cash tracking</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>HMRC-ready exports</li>\n          </ul>\n\n          <div class=\"pricing-features-header\">Meetings &amp; dues</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Summons workflow</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>RSVPs &amp; dietary tracking</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Bulk dues &amp; reminders</li>\n          </ul>\n\n          <a class=\"btn pricing-cta\" data-route=\"contact\">Get a walkthrough</a>\n        </div>\n\n        <div class=\"pricing-card featured\">\n          <div class=\"pricing-tag\">Most Lodges Choose This</div>\n          <div class=\"pricing-name\">Complete</div>\n          <div class=\"pricing-price\"><span class=\"from\">From</span>£229<span class=\"per\">/mo</span></div>\n          <div class=\"pricing-period\">billed annually · or £259 monthly</div>\n          <div class=\"pricing-desc\">Everything in Essentials, plus the AI assistant, candidate pipeline, Almoner welfare, and full reporting suite.</div>\n\n          <div class=\"pricing-features-header\">Everything in Essentials, plus:</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>AI assistant for drafting</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Members-at-risk insights</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Post-meeting summaries</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Data quality checks</li>\n          </ul>\n\n          <div class=\"pricing-features-header\">Membership &amp; care</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Candidate CRM &amp; pipeline</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Almoner welfare cases</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Mentor assignment &amp; sign-off</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Charity campaigns</li>\n          </ul>\n\n          <div class=\"pricing-features-header\">Reports &amp; compliance</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Charity &amp; recruitment reports</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Full audit trail</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>SAR &amp; consent management</li>\n          </ul>\n\n          <a class=\"btn pricing-cta\" data-route=\"contact\">Get a walkthrough</a>\n        </div>\n\n        <div class=\"pricing-card\">\n          <div class=\"pricing-tag\">2 to 6 lodges</div>\n          <div class=\"pricing-name\">Group</div>\n          <div class=\"pricing-price\"><span class=\"from\">From</span>£349<span class=\"per\">/mo</span></div>\n          <div class=\"pricing-period\">2 lodges · then £119 per extra</div>\n          <div class=\"pricing-desc\">Everything in Complete for halls, groups, or connected lodges with shared oversight and central billing.</div>\n\n          <div class=\"pricing-features-header\">Everything in Complete, plus:</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Separate lodge records</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Per-lodge branding &amp; site</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Cross-lodge reporting</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Central billing, one invoice</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Lodge context switching</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Multi-lodge member visibility</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Shared rollout support</li>\n          </ul>\n\n          <a class=\"btn pricing-cta\" data-route=\"contact\">Get a walkthrough</a>\n        </div>\n\n        <div class=\"pricing-card\">\n          <div class=\"pricing-tag\">Provincial Rollout</div>\n          <div class=\"pricing-name\">Province</div>\n          <div class=\"pricing-price\"><span class=\"from\">From</span>£2k<span class=\"per\">/mo</span></div>\n          <div class=\"pricing-period\">+ £35 per lodge · typically £4,500/mo</div>\n          <div class=\"pricing-desc\">Province-wide rollout, central oversight, migration planning, and ongoing support.</div>\n\n          <div class=\"pricing-features-header\">Everything in Complete, plus:</div>\n          <ul class=\"pricing-features\">\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Operator console</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Province-wide dashboards</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Annual returns CSV (one click)</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Bulk lodge operations</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Health-style portfolio signals</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Migration planning included</li>\n            <li><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Named provincial contact</li>\n          </ul>\n\n          <a class=\"btn pricing-cta\" data-route=\"contact\">Talk to us</a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- FAQ -->\n  <section class=\"faq-section\">\n    <div class=\"container\">\n      <div class=\"faq-grid\">\n        <div>\n          <div class=\"eyebrow\">Common questions</div>\n          <h2 class=\"display\">Pricing, plainly answered.</h2>\n          <p class=\"body-text\" style=\"margin-top: 20px;\">If your question isn't here, the walkthrough is the fastest way to get a precise answer.</p>\n          <a class=\"btn btn-primary\" data-route=\"contact\" style=\"margin-top: 24px;\">Book a walkthrough</a>\n        </div>\n\n        <div class=\"faq-list\">\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">How does the Gift Aid claim actually work?</div>\n            <div class=\"faq-a\">LodgePay records every eligible payment, ties it to a member's Gift Aid declaration, and produces an HMRC-ready report. The lodge or province files the claim with HMRC and receives the reclaim direct to its bank account. We don't touch the money.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">What is GASDS and why does it matter?</div>\n            <div class=\"faq-a\">The Gift Aid Small Donations Scheme lets charities reclaim a Gift Aid equivalent on small cash donations up to £8,000 per year, without needing declarations. Cash collections at the festive board often qualify. Most lodges miss this entirely. LodgePay tracks the cash and surfaces what's reclaimable.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">Are payment processing fees included?</div>\n            <div class=\"faq-a\">No. Mooov handles payment processing on lodges' behalf. Standard payment processing fees apply, passed through at cost. We don't mark them up. Our pricing is for the platform itself.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">Can a lodge start small?</div>\n            <div class=\"faq-a\">Yes. Start with Essentials. Most lodges add Complete features within their first year as the candidate pipeline and Almoner module become important. Upgrading is one click and we'll move existing data automatically.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">Is there a setup fee?</div>\n            <div class=\"faq-a\">No setup fee on any tier. Onboarding is included: branding setup, Mooov configuration, officer training, and a guided first month. Provincial rollouts include migration planning as standard.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">Can the lodge try it before committing?</div>\n            <div class=\"faq-a\">Yes. We offer a free walkthrough where we set up a sandbox with the lodge's branding so officers can see exactly how it would work before deciding.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">What about data security?</div>\n            <div class=\"faq-a\">Lodge data is tenant-isolated, encrypted in transit and at rest, with PCI scope managed by Mooov and underlying providers. MFA for admin users. Gift Aid records are retained for the seven years HMRC requires. The audit trail logs every sensitive action.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">Can we cancel?</div>\n            <div class=\"faq-a\">Annual plans renew yearly. Monthly plans cancel any time with one month's notice. Lodge data exports as standard CSV at any point so the lodge keeps its records.</div>\n          </div>\n          <div class=\"faq-item\">\n            <div class=\"faq-q\">How do Provinces buy?</div>\n            <div class=\"faq-a\">Talk to us. Provincial pricing depends on lodge count and rollout scope. Most provinces start with a small pilot of three to five lodges, prove the case at provincial council, then roll out. We help with the business case, the data migration, and the officer training.</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n</main>\n\n<!-- ============ CONTACT PAGE ============ -->\n<main class=\"page\" data-page=\"contact\">\n\n  <section class=\"contact-hero\">\n    <div class=\"container-narrow\" style=\"text-align: center;\">\n      <div class=\"eyebrow\">Talk to us</div>\n      <h1 class=\"display\">Book a walkthrough on your lodge.</h1>\n      <p class=\"lede\" style=\"max-width: 720px; margin: 20px auto 0;\">A 30-minute session where we set up a sandbox with your lodge's branding and walk you through exactly how it would work, with your numbers.</p>\n    </div>\n  </section>\n\n  <div class=\"container\">\n    <div class=\"contact-grid\">\n      <div class=\"contact-side\">\n        <h2>Get in touch</h2>\n        <p class=\"body-text\">Whether you're a Secretary curious about the platform, a Treasurer who wants the Gift Aid story properly explained, or a Provincial team weighing a rollout, we'll find the right format.</p>\n\n        <div class=\"contact-method\">\n          <div class=\"contact-method-icon\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z\"/><polyline points=\"22,6 12,13 2,6\"/></svg>\n          </div>\n          <div class=\"contact-method-content\">\n            <div class=\"contact-method-label\">Email</div>\n            <div class=\"contact-method-value\">hello@lodgepayments.co.uk</div>\n            <div class=\"contact-method-detail\">For demos, enquiries, and provincial conversations</div>\n          </div>\n        </div>\n\n        <div class=\"contact-method\">\n          <div class=\"contact-method-icon\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z\"/><circle cx=\"12\" cy=\"10\" r=\"3\"/></svg>\n          </div>\n          <div class=\"contact-method-content\">\n            <div class=\"contact-method-label\">Office</div>\n            <div class=\"contact-method-value\">Chelmsford, Essex</div>\n            <div class=\"contact-method-detail\">Visits by appointment for provincial teams</div>\n          </div>\n        </div>\n\n        <div class=\"contact-method\">\n          <div class=\"contact-method-icon\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"/><line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"/><line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>\n          </div>\n          <div class=\"contact-method-content\">\n            <div class=\"contact-method-label\">Walkthroughs</div>\n            <div class=\"contact-method-value\">30 minutes · Free · No commitment</div>\n            <div class=\"contact-method-detail\">Book via the form, or write directly</div>\n          </div>\n        </div>\n      </div>\n\n      <form class=\"contact-form\">\n        <div class=\"form-eyebrow\">Walkthrough request</div>\n        <div class=\"form-title\">Tell us about your lodge</div>\n\n        <div class=\"form-row\">\n          <div class=\"form-field\">\n            <label class=\"form-label\">First name</label>\n            <input type=\"text\" name=\"first_name\" class=\"form-input\" required>\n          </div>\n          <div class=\"form-field\">\n            <label class=\"form-label\">Last name</label>\n            <input type=\"text\" name=\"last_name\" class=\"form-input\" required>\n          </div>\n        </div>\n\n        <div class=\"form-field\">\n          <label class=\"form-label\">Email</label>\n          <input type=\"email\" name=\"work_email\" class=\"form-input\" required>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-field\">\n            <label class=\"form-label\">Lodge name</label>\n            <input type=\"text\" name=\"lodge_name\" class=\"form-input\" required>\n            <div class=\"form-help\">e.g. St Aubyn's Lodge No. 1858</div>\n          </div>\n          <div class=\"form-field\">\n            <label class=\"form-label\">Your role</label>\n            <select name=\"role\" class=\"form-select\" required>\n              <option value=\"\">Select a role</option>\n              <option>Secretary</option>\n              <option>Treasurer</option>\n              <option>Charity Steward</option>\n              <option>Membership Officer</option>\n              <option>Almoner</option>\n              <option>Mentor</option>\n              <option>Master / DC</option>\n              <option>Provincial team</option>\n              <option>Other</option>\n            </select>\n          </div>\n        </div>\n\n        <div class=\"form-field\">\n          <label class=\"form-label\">What you'd like to see</label>\n          <select name=\"walkthrough_focus\" class=\"form-select\" required>\n            <option value=\"\">Select an option</option>\n            <option>Single lodge - full walkthrough</option>\n            <option>Single lodge - Gift Aid &amp; Treasurer focus</option>\n            <option>Lodge group / hall - multi-lodge setup</option>\n            <option>Provincial rollout - strategic conversation</option>\n            <option>I'd like the team to recommend</option>\n          </select>\n        </div>\n\n        <div class=\"form-field\">\n          <label class=\"form-label\">Anything we should know? (optional)</label>\n          <textarea name=\"notes\" class=\"form-textarea\" placeholder=\"Specific questions, current tools you'd be replacing, timeline...\"></textarea>\n        </div>\n\n        <button type=\"submit\" class=\"btn btn-primary form-submit\">Request walkthrough</button>\n        <div class=\"form-foot\">We'll be back within one working day. No spam, no follow-up sequences.</div>\n      </form>\n\n      <div id=\"form-success\" style=\"display: none; background: var(--royal-soft); border: 1px solid var(--royal-line); border-radius: 12px; padding: 56px 48px; text-align: center; grid-column: 2;\">\n        <svg width=\"48\" height=\"48\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--royal)\" stroke-width=\"2\" style=\"margin-bottom: 24px;\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <div class=\"form-title\">Thank you</div>\n        <p class=\"body-text\">We'll be in touch within one working day with a few suggested times for your walkthrough.</p>\n      </div>\n    </div>\n  </div>\n\n</main>\n\n<!-- ============ FOOTER ============ -->\n<footer class=\"footer\">\n  <div class=\"container\">\n    <div class=\"footer-grid\">\n      <div class=\"footer-brand\">\n        <img src=\"data:image/png;base64,\" alt=\"LodgePay\">\n        <p class=\"footer-tag\">An operating system for lodge teams. Websites, payments, events, charity, and candidates, on one record.</p>\n      </div>\n      <div class=\"footer-col\">\n        <h4>Product</h4>\n        <ul>\n          <li><a data-route=\"home\">Overview</a></li>\n          <li><a data-route=\"features\">Features</a></li>\n          <li><a data-route=\"pricing\">Pricing</a></li>\n          <li><a data-route=\"contact\">Book a demo</a></li>\n        </ul>\n      </div>\n      <div class=\"footer-col\">\n        <h4>Company</h4>\n        <ul>\n          <li><a>About</a></li>\n          <li><a>News</a></li>\n          <li><a data-route=\"contact\">Contact</a></li>\n        </ul>\n      </div>\n      <div class=\"footer-col\">\n        <h4>Support</h4>\n        <ul>\n          <li><a>FAQ</a></li>\n          <li><a>Technical support</a></li>\n          <li><a>Documentation</a></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"footer-base\">\n      <span>&copy; MMXXVI NEURAL NETWORK GROUP LIMITED. All rights reserved.</span>\n      <div class=\"footer-base-links\">\n        <a href=\"/privacy\">Privacy</a>\n        <a href=\"/terms\">Terms</a>\n        <a href=\"/gdpr\">GDPR</a>\n        <a href=\"/cookies\">Cookies</a>\n        <button type=\"button\" data-cookie-settings>Cookie settings</button>\n      </div>\n    </div>\n  </div>\n</footer>";

const ROUTE_TO_PATH: Record<MarketingSitePage, string> = {
  home: "/",
  features: "/features",
  contact: "/contact",
};

const PATH_TO_ROUTE: Record<string, MarketingSitePage> = {
  "/": "home",
  "/features": "features",
  "/contact": "contact",
  "/book-demo": "contact",
};

function routeFromLocation(initialPage: MarketingSitePage): MarketingSitePage {
  if (typeof window === "undefined") return initialPage;
  return PATH_TO_ROUTE[window.location.pathname] ?? initialPage;
}

function isMarketingRoute(value: string | null): value is MarketingSitePage {
  return value === "home" || value === "features" || value === "contact";
}

export function StaticMarketingSite({ initialPage }: { initialPage: MarketingSitePage }) {
  useEffect(() => {
    let observer: IntersectionObserver | null = null;

    const applyRoute = (route: MarketingSitePage, pushHistory: boolean) => {
      document.querySelectorAll<HTMLElement>(".page").forEach((page) => {
        page.classList.toggle("active", page.dataset.page === route);
      });

      document.querySelectorAll<HTMLElement>(".nav-link").forEach((link) => {
        link.classList.toggle("active", link.dataset.route === route);
      });

      document.querySelector<HTMLElement>(".nav")?.classList.remove("mobile-open");
      const menuToggle = document.querySelector<HTMLElement>(".mobile-nav-toggle");
      menuToggle?.setAttribute("aria-expanded", "false");
      menuToggle?.setAttribute("aria-label", "Open menu");

      if (pushHistory) {
        window.history.pushState(null, "", ROUTE_TO_PATH[route]);
      }

      window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior });
    };

    const handleClick = (event: MouseEvent) => {
      if (!(event.target instanceof Element)) return;

      const menuToggle = event.target.closest<HTMLElement>(".mobile-nav-toggle");
      if (menuToggle) {
        event.preventDefault();
        const nav = document.querySelector<HTMLElement>(".nav");
        const isOpen = nav?.classList.toggle("mobile-open") ?? false;
        menuToggle.setAttribute("aria-expanded", String(isOpen));
        menuToggle.setAttribute("aria-label", isOpen ? "Close menu" : "Open menu");
        return;
      }

      const routedElement = event.target.closest<HTMLElement>("[data-route]");
      const route = routedElement?.dataset.route ?? null;
      if (isMarketingRoute(route)) {
        event.preventDefault();
        applyRoute(route, true);
        return;
      }

      const question = event.target.closest<HTMLElement>(".faq-q");
      if (question?.parentElement) {
        question.parentElement.classList.toggle("open");
      }
    };

    const handleSubmit = async (event: SubmitEvent) => {
      const form = event.target;
      if (!(form instanceof HTMLFormElement) || !form.classList.contains("contact-form")) {
        return;
      }

      event.preventDefault();
      const submitButton = form.querySelector<HTMLButtonElement>("button[type='submit']");
      const success = document.getElementById("form-success");
      const formData = new FormData(form);
      const focus = String(formData.get("walkthrough_focus") ?? "").trim();
      const notes = String(formData.get("notes") ?? "").trim();
      const firstName = String(formData.get("first_name") ?? "").trim();
      const lastName = String(formData.get("last_name") ?? "").trim();

      if (submitButton) {
        submitButton.disabled = true;
        submitButton.textContent = "Sending...";
      }

      try {
        const response = await fetch("/api/demo-requests", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            full_name: [firstName, lastName].filter(Boolean).join(" "),
            work_email: String(formData.get("work_email") ?? "").trim(),
            lodge_name: String(formData.get("lodge_name") ?? "").trim(),
            role: String(formData.get("role") ?? "").trim(),
            lodge_count: 1,
            priorities: [focus, notes].filter(Boolean).join("\n\n"),
          }),
        });

        if (!response.ok) {
          const body = await response.json().catch(() => ({}));
          throw new Error(body.error ?? "Could not submit walkthrough request.");
        }

        if (success) success.style.display = "block";
        form.style.display = "none";
      } catch (error) {
        alert(error instanceof Error ? error.message : "Could not submit walkthrough request.");
      } finally {
        if (submitButton) {
          submitButton.disabled = false;
          submitButton.textContent = "Request walkthrough";
        }
      }
    };

    const handlePopState = () => applyRoute(routeFromLocation(initialPage), false);

    document.addEventListener("click", handleClick);
    document.addEventListener("submit", handleSubmit);
    window.addEventListener("popstate", handlePopState);
    applyRoute(routeFromLocation(initialPage), false);

    const revealElements = document.querySelectorAll<HTMLElement>(
      ".layer-card, .replaces-card, .pricing-card",
    );

    if (!("IntersectionObserver" in window)) {
      revealElements.forEach((element) => element.classList.add("reveal", "in"));
    } else {
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              entry.target.classList.add("in");
              observer?.unobserve(entry.target);
            }
          });
        },
        { threshold: 0.1 },
      );

      revealElements.forEach((element) => {
        element.classList.add("reveal");
        observer?.observe(element);
      });
    }

    return () => {
      document.removeEventListener("click", handleClick);
      document.removeEventListener("submit", handleSubmit);
      window.removeEventListener("popstate", handlePopState);
      observer?.disconnect();
    };
  }, [initialPage]);

  // Reflect existing admin/member session in the static nav so returning
  // signed-in visitors aren't told to "Login" every time they hit the
  // marketing root. The session cookies (covenant_admin_session,
  // covenant_staff_admin_session, sb-*-auth-token) already persist for days;
  // we just weren't surfacing it here.
  useEffect(() => {
    let cancelled = false;

    const findLoginAnchors = () =>
      Array.from(
        document.querySelectorAll<HTMLAnchorElement>(
          'a[href="/admin/login"], a[data-marketing-login]'
        )
      );

    const applyViewer = (
      destination: string,
      label: string,
      sessionKey: string
    ) => {
      if (cancelled) return;
      for (const anchor of findLoginAnchors()) {
        if (anchor.dataset.marketingLoginState === sessionKey) continue;
        anchor.setAttribute("href", destination);
        anchor.textContent = label;
        anchor.dataset.marketingLogin = "true";
        anchor.dataset.marketingLoginState = sessionKey;
      }
    };

    async function resolve() {
      try {
        const [adminRes, memberRes] = await Promise.all([
          fetch("/api/auth/session", { cache: "no-store" }).catch(() => null),
          fetch("/api/auth/member/session", { cache: "no-store" }).catch(
            () => null
          ),
        ]);

        if (cancelled) return;

        if (adminRes && adminRes.ok) {
          const data = await adminRes.json().catch(() => null);
          if (data && data.authenticated) {
            applyViewer("/admin", "Open dashboard", "admin");
            return;
          }
        }

        if (memberRes && memberRes.ok) {
          const data = await memberRes.json().catch(() => null);
          if (data && data.user) {
            applyViewer("/member", "Open portal", "member");
            return;
          }
        }
      } catch {
        // Stay on the guest "Login" CTA if the auth API is unreachable.
      }
    }

    void resolve();
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className="lodgepay-marketing-site">
      <style dangerouslySetInnerHTML={{ __html: SITE_CSS }} />
      <style
        dangerouslySetInnerHTML={{
          __html:
            '[data-route="pricing"], [data-page="pricing"] { display: none !important; }',
        }}
      />
      <div dangerouslySetInnerHTML={{ __html: SITE_HTML }} />
    </div>
  );
}
